#!/usr/bin/env bash
# GENERATED by pve/build.sh from pve/install-parts: do not edit, edit the parts and rebuild (install.sh).
# cloud-desktop-host in an unprivileged Proxmox LXC: idempotent installer.
#
# Run on the Proxmox host as root. This script does the HOST half (driver, modules,
# input guard, the LXC and its config); everything inside the container is done by
# pve/ct-install.sh, which this script pushes into the CT and runs there (it can also
# be run on its own in any container/VM, see its header). Binary, scripts and configs
# come from the GitHub release (built by .github/workflows/release.yml), unless run from
# a repo checkout that has dist/cloud-desktop-host (docker build -o dist .).
#
#   bash -c "$(curl -fsSL https://raw.githubusercontent.com/chiririll/cloud-desktop-host/main/pve/install.sh)" -- --check
#   bash -c "$(curl -fsSL https://raw.githubusercontent.com/chiririll/cloud-desktop-host/main/pve/install.sh)"
#   ./pve/install.sh [--check] [--update] [--distro ubuntu-26.04]   # from a checkout
#
# --update brings everything to the latest version (packages, Sunshine, Cloud Mouse, CDH
# bundle) and restarts the session if no client is connected; --force-restart restarts anyway.
#
# Every step: check → (apply if needed) → check again. Safe to re-run any time,
# e.g. after a host driver update or when /dev/dri/cardN got renumbered.
#
# The container ID is asked interactively (or set CTID=… for unattended runs).
# Creation settings are asked only when a new CT is about to be created.
#
# Settings (env vars, all optional when run interactively):
#   CTID  CT_HOSTNAME  CT_STORAGE  CT_DISK  CT_CORES  CT_MEMORY  CT_BRIDGE
#   CT_IP=dhcp|192.168.1.50/24   CT_GATEWAY=192.168.1.1   (static address; gateway asked/guessed from the host's route)
#   TEMPLATE_STORAGE=local  CT_USER=user  SHM_SIZE=4G
#   DISTRO=fedora-43|fedora-44|fedora-45|ubuntu-26.04   distro of the CT (same as --distro; asked when
#                     creating a CT, an existing running CT is detected). Must have a release bundle.
#                     FEDORA=44 / --fedora 44 still work (= fedora-44).
#   INSTALL_STEAM=1|0   Steam + Gamescope + MangoHud (asked; default yes without a tty)
#   YES=1   don't ask for confirmation before changing an existing CT
#   NVIDIA_PCI=0000:01:00.0   pick the GPU if there are several NVIDIA cards
#   CDH_VERSION=v1.0.0   use this release (default: local dist/, else latest)
#   CDH_GH_REPO=chiririll/cloud-desktop-host   SUNSHINE_PKG=<url or local .rpm/.deb>   SUNSHINE_VERSION=<tag>
#   CLOUD_MOUSE_PKG=<url or local .rpm/.deb>   (default: latest kcm-cloud-mouse release for the distro, skipped with a warning if there is none; "none" to skip)
#   (SUNSHINE_RPM / CLOUD_MOUSE_RPM are accepted as old names)
#   INSTALL_UPDATE_TIMER=1   weekly systemd timer inside the CT that runs ct-install.sh --update
#   INSTALL_INPUT_GUARD=0   don't install the cdh_input_guard host kernel module (default 1).
#                     Without it the CT shares the host's /dev/input with every other such CT.
#   CDH_GUARD_REPO, CDH_GUARD_VERSION   where the module release comes from
#   CSRF_EXTRA=https://gaming.example.org   extra Sunshine web UI origins
set -euo pipefail

# ════ install-parts/files/* (inlined by build.sh) ════
get_file() {
  case $1 in
    bin/cdh-input-node.sh)
      cat <<'CDH_EMBEDDED_EOF'
#!/bin/bash
# cdh-input-node add|remove <eventN|jsN>
# cdh-input-node sync
#
# Written by cloud-desktop-host pve/install.sh; a re-run overwrites it.
#
# Gives each container only the virtual input devices it created. cdh_input_guard
# records the cgroup of the process that created a uinput device in the root-only
# sysfs attribute cdh_owner_cgroup. For a device created inside CT <id> this makes
# /dev/cdh-input/<id>/<node>, owned by the uid in /etc/cdh-input/<id>.uid; that
# directory is the CT's /dev/input. A device with no owner (created before the
# module loaded, or by the host) is given to nobody.
#
# udev runs add/remove (72-cdh-input-node.rules); install.sh runs sync.
set -u
shopt -s nullglob
PATH=/usr/sbin:/usr/bin:/sbin:/bin
SYS=/sys/class/input
ROOT=/dev/cdh-input
CONF=/etc/cdh-input

valid() { [[ $1 =~ ^(event|js)[0-9]+$ ]]; }

# Prints the id of the CT that created the device, nothing if there is none.
# The attribute is untrusted: below /lxc/<id>/ the container names its own
# cgroups, so only the start of the path is used.
owner_ct() {
  local f=$SYS/$1/device/cdh_owner_cgroup path=
  [[ -r $f ]] || return 0
  IFS= read -r path <"$f" || true
  if [[ $path =~ ^/lxc/([0-9]+)/ ]]; then echo "${BASH_REMATCH[1]}"; fi
}

# drop <node> [ct]: remove the node from every CT directory except ct's
drop() {
  local d
  for d in "$ROOT"/*/; do
    [[ $d == "$ROOT/${2:-}/" ]] || rm -f -- "$d$1"
  done
}

add() {
  local name=$1 ct dir uid major='' minor='' node tmp
  ct=$(owner_ct "$name")
  # The kernel reuses names and minors: a leftover node with this name in another
  # CT's directory would now open this device.
  drop "$name" "$ct"
  [[ -n $ct ]] || return 0
  dir=$ROOT/$ct
  [[ -d $dir ]] || return 0                    # not a CT set up by install.sh
  uid=$(cat "$CONF/$ct.uid" 2>/dev/null)
  [[ $uid =~ ^[0-9]+$ ]] || return 0
  [[ -r $SYS/$name/dev ]] || return 0          # gone again
  IFS=: read -r major minor <"$SYS/$name/dev" || true
  [[ $major == 13 && $minor =~ ^[0-9]+$ ]] || return 0

  node=$dir/$name
  if [[ -c $node && ! -L $node &&
        $(stat -c '%u %a %t %T' "$node") == "$(printf '%s 600 %x %x' "$uid" "$major" "$minor")" ]]; then
    return 0
  fi
  # Finish the node under a name the CT ignores, then rename it into place.
  tmp=$dir/.$name.new
  rm -f -- "$tmp"
  if mknod -m 0600 "$tmp" c "$major" "$minor" && chown "$uid" "$tmp" && mv -fT -- "$tmp" "$node"; then
    return 0
  fi
  rm -f -- "$tmp"
  return 1
}

sync() {
  local node name ct s rc=0
  for node in "$ROOT"/*/* "$ROOT"/*/.[!.]*; do
    name=${node##*/}
    ct=${node%/*}; ct=${ct##*/}
    if ! valid "$name" || [[ ! -e $SYS/$name || $(owner_ct "$name") != "$ct" ]]; then
      rm -f -- "$node"
    fi
  done
  for s in "$SYS"/event* "$SYS"/js*; do
    add "${s##*/}" || rc=1
  done
  return $rc
}

[[ -d $ROOT ]] || exit 0                       # no CT uses this yet
exec 9>"$ROOT/.lock" || exit 1
flock 9 || exit 1                              # udev runs one of these per device, in parallel

case ${1:-} in
  add|remove)
    valid "${2:-}" || { echo "cdh-input-node: bad node name '${2:-}'" >&2; exit 2; }
    if [[ $1 == add ]]; then add "$2"; else drop "$2"; fi
    ;;
  sync) sync ;;
  *) echo "usage: cdh-input-node add|remove <eventN|jsN> | sync" >&2; exit 2 ;;
esac
CDH_EMBEDDED_EOF
      ;;
    udev/72-cdh-input-node.rules)
      cat <<'CDH_EMBEDDED_EOF'
# Per-container /dev/input, see /usr/local/sbin/cdh-input-node.
# Written by cloud-desktop-host pve/install.sh; a re-run overwrites it.
#
# cdh_input_guard sends "change" once the owner attribute exists, so the helper
# runs on add and on change. It reads the owner from sysfs itself: the container
# names part of that path, so it must not be substituted into RUN here.

SUBSYSTEM!="input", GOTO="cdh_input_node_end"
KERNEL!="event*|js*", GOTO="cdh_input_node_end"
DEVPATH!="/devices/virtual/input/*", GOTO="cdh_input_node_end"

ACTION=="remove", RUN+="/usr/local/sbin/cdh-input-node remove %k"
ACTION=="add|change", RUN+="/usr/local/sbin/cdh-input-node add %k"

LABEL="cdh_input_node_end"
CDH_EMBEDDED_EOF
      ;;
    *) echo "get_file: no file $1" >&2; return 1 ;;
  esac
}

# ════ install-parts/10-config.sh ════
# ── settings: defaults, env overrides, CLI ─────────────────────
CTID=${CTID:-}
CT_HOSTNAME=${CT_HOSTNAME:-}
CT_STORAGE=${CT_STORAGE:-}
CT_DISK=${CT_DISK:-}
CT_CORES=${CT_CORES:-}
CT_MEMORY=${CT_MEMORY:-}
CT_BRIDGE=${CT_BRIDGE:-}
CT_IP=${CT_IP:-}             # "dhcp" or a static address in CIDR form, e.g. 192.168.1.50/24
CT_GATEWAY=${CT_GATEWAY:-}   # only used with a static CT_IP
YES=${YES:-0}
TEMPLATE_STORAGE=${TEMPLATE_STORAGE:-local}
DISTRO=${DISTRO:-${FEDORA:+fedora-$FEDORA}}
SUPPORTED_DISTROS=(fedora-43 fedora-44 fedora-45 ubuntu-26.04)   # keep in sync with the matrix in .github/workflows/release.yml
DEFAULT_DISTRO=fedora-43
CT_USER=${CT_USER:-user}
INSTALL_STEAM=${INSTALL_STEAM:-}
SHM_SIZE=${SHM_SIZE:-4G}
NVIDIA_PCI=${NVIDIA_PCI:-}
CSRF_EXTRA=${CSRF_EXTRA:-}

CDH_GH_REPO=${CDH_GH_REPO:-chiririll/cloud-desktop-host}
CDH_VERSION=${CDH_VERSION:-}
# host kernel module that keeps container input away from the host console
INSTALL_INPUT_GUARD=${INSTALL_INPUT_GUARD:-1}
CDH_GUARD_REPO=${CDH_GUARD_REPO:-chiririll/cdh-input-guard}
CDH_GUARD_VERSION=${CDH_GUARD_VERSION:-}   # empty = latest release
REPO=$(cd "$(dirname "${BASH_SOURCE[0]:-.}")/.." && pwd)
CDH_BIN=$REPO/dist/cloud-desktop-host
# Local build (dist/ of a checkout): pushed into the CT instead of a release download. It must be
# built for the CT's distro (docker build --build-arg BASE=… -o dist .).
SUNSHINE_PKG=${SUNSHINE_PKG:-${SUNSHINE_RPM:-}}
SUNSHINE_VERSION=${SUNSHINE_VERSION:-}
CLOUD_MOUSE_PKG=${CLOUD_MOUSE_PKG:-${CLOUD_MOUSE_RPM:-}}
INSTALL_UPDATE_TIMER=${INSTALL_UPDATE_TIMER:-0}
CT_CDH=/opt/cloud-desktop-host   # scripts + configs, root-owned, read-only for the user
CT_INSTALLER=$REPO/pve/ct-install.sh   # the in-container script: checkout, else the release asset
LOG=/var/log/cdh-lxc-install.log
LOG_CT=/var/log/cdh-ct-install.log   # written by ct-install.sh inside the CT

# ── runtime state (set while running, read across parts) ──
CHECK_ONLY=0
CONF=''          # /etc/pve/lxc/<CTID>.conf
CT_NAME=''       # hostname of the CT if it already exists, empty = will be created
BUNDLE_TMP=''    # temp dir for the downloaded ct-install.sh, removed on exit
UPDATE=0         # --update
FORCE_RESTART=0  # --force-restart
OS_TYPE=fedora   # pct --ostype of a new CT
NEEDED=0         # steps still needed (--check)
RESTART_CT=0     # a step changed the CT config: restart before going inside
APPLIED=0        # set by step() when it changed something
SKIPPED=0        # --check could not look inside the CT (missing / stopped), see skip_rest()

usage() { local IFS='|'; echo "usage: install.sh [--check] [--update [--force-restart]] [--distro ${SUPPORTED_DISTROS[*]}]   (settings: see the script header)"; }

parse_args() {
  while (($#)); do
    case "$1" in
      --check|-n) CHECK_ONLY=1 ;;
      --update|-u) UPDATE=1 ;;
      --force-restart) FORCE_RESTART=1 ;;
      --distro=*) DISTRO=${1#*=} ;;
      --distro|-d) [[ $# -ge 2 ]] || { usage; exit 2; }; DISTRO=$2; shift ;;
      --fedora=*) DISTRO=fedora-${1#*=} ;;
      --fedora|-f) [[ $# -ge 2 ]] || { usage; exit 2; }; DISTRO=fedora-$2; shift ;;
      -h|--help) usage; exit 0 ;;
      *) echo "unknown option: $1"; usage; exit 2 ;;
    esac
    shift
  done
}

# ════ install-parts/shared/20-engine.sh ════
# ════════════════════════════════════════════════════════════════
# Shared by install.sh (host) and ct-install.sh (container): output, step engine, embedded files.
#   1. output          msg_*, die, header
#   2. step engine     why, step, require
#   3. embedded files  render_file
# ════════════════════════════════════════════════════════════════

# ── 1. output, community-scripts style ─────────────────────────
if [[ -t 1 || ${CDH_COLOR:-} == 1 ]]; then
  GN=$'\e[32m' YW=$'\e[33m' RD=$'\e[31m' BL=$'\e[36m' DM=$'\e[2m' CL=$'\e[0m'
else
  GN='' YW='' RD='' BL='' DM='' CL=''
fi
msg_info() { printf ' %s…%s %s' "$YW" "$CL" "$1"; }
msg_ok()   { printf '\r\e[K %s✔%s %s%s%s\n' "$GN" "$CL" "$1" "$DM" "${2:+ ($2)}$CL"; }
msg_todo() { printf '\r\e[K %s◦%s %s %s(needed)%s\n' "$BL" "$CL" "$1" "$YW" "$CL"; }
msg_warn() { printf '\r\e[K %s!%s %s\n' "$YW" "$CL" "$1"; }
die()      { printf '\r\e[K %s✘%s %s\n' "$RD" "$CL" "$1"; exit 1; }
header()   { printf '\n%s── %s%s\n' "$BL" "$1" "$CL"; }


APPLIED_ANY=0    # steps applied in this run (update mode: restart the session if > 0)

# ── 2. step engine ─────────────────────────────────────────────
# step "description" check apply
#   check/apply are function names; extra words become arguments
#   ("chk_nocaps sunshine"), so one pair of functions can serve several steps.
#   Checks print WHY they fail (one reason per line, see why()); shown under "needed".
#   Globals: CHECK_ONLY (read), NEEDED (counted in --check), APPLIED (set to 1 if applied).
# require "description" check "hint": a check we can't fix automatically.

# why <reason>: print the reason and fail; the last line of a failing check
why() { echo "$*"; return 1; }

# show_why <check output>: first lines of a check's output, dimmed and indented
show_why() { [[ -n $1 ]] && sed -n '1,8p' <<<"$1" | sed "s/^/     $DM/; s/\$/$CL/"; return 0; }

step() {
  local name=$1 check=$2 apply=$3 rc out
  APPLIED=0

  if out=$($check 2>&1); then msg_ok "$name"; return 0; fi

  if ((CHECK_ONLY)); then
    msg_todo "$name"; show_why "$out"
    NEEDED=$((NEEDED + 1))
    return 0
  fi

  msg_info "$name"
  printf '=== %s %s\n%s\n' "$(date -Is)" "$name" "$out" >>"$LOG"
  set +e; ( set -e; $apply ) >>"$LOG" 2>&1; rc=$?; set -e
  ((rc == 0)) || die "$name: failed (exit $rc), see $LOG"

  if ! out=$($check 2>&1); then
    printf '\r\e[K'; show_why "$out"
    die "$name: still not satisfied after applying, see $LOG"
  fi
  APPLIED=1; APPLIED_ANY=$((APPLIED_ANY + 1))
  msg_ok "$name" "done"
}

require() {
  local name=$1 check=$2 hint=$3 out
  out=$($check 2>&1) && { msg_ok "$name"; return 0; }
  if ((CHECK_ONLY)); then
    msg_todo "$name: $hint"; show_why "$out"
    NEEDED=$((NEEDED + 1))
    return 0
  fi
  show_why "$out"; die "$name: $hint"
}

# call right after a step whose change needs a CT restart
restart_if_applied() { if ((APPLIED)); then RESTART_CT=1; fi; }


# ── 3. embedded files ──────────────────────────────────────────
# install-parts/files/* are inlined by build.sh into get_file() (see build.sh), so the
# installer stays one file. Files may hold @VAR@ placeholders.

# render_file <file> [VAR…]: the file with every @VAR@ replaced by the value of $VAR
render_file() {
  local out v; out=$(get_file "$1"); shift
  for v; do out=${out//@$v@/${!v}}; done
  printf '%s\n' "$out"
}

# ════ install-parts/shared/30-release.sh ════
# ── release bundle: cdh/{cloud-desktop-host,scripts,configs,pve} ──
# Shared: the host script fetches ct-install.sh from the release, ct-install.sh fetches the bundle.
# MANIFEST: "sha256  path" for cloud-desktop-host, scripts/*, configs/*.
# --check only needs this (a few KB), the bundle is downloaded to apply.
release_base() {
  if [[ -z $CDH_VERSION || $CDH_VERSION == latest ]]; then
    echo "https://github.com/$CDH_GH_REPO/releases/latest/download"
  else
    echo "https://github.com/$CDH_GH_REPO/releases/download/$CDH_VERSION"
  fi
}
# The release MANIFEST has one binary line per distro (cloud-desktop-host-<DISTRO_TAG>-x86_64, e.g.
# -fc43- or -ubuntu2604-); keep ours under the plain name used by local_manifest and drop the others.
fetch_manifest() {
  local raw
  raw=$(curl -fsSL "$(release_base)/MANIFEST") || return 1
  MANIFEST=$(sed -n -e "s|  cloud-desktop-host-$DISTRO_TAG-x86_64\$|  cloud-desktop-host|p" \
                    -e '/  cloud-desktop-host-/d;/  \(scripts\|configs\)\//p' <<<"$raw")
  [[ -n $MANIFEST ]]
}
local_manifest() {
  printf '%s  cloud-desktop-host\n' "$(sha256sum <"$CDH_BIN" | cut -d' ' -f1)"
  (cd "$REPO" && find scripts configs -type f | sort | xargs sha256sum)
}
# release lines of MANIFEST that belong inside the CT (scripts/, configs/)
manifest() { grep -E '  (scripts|configs)/' <<<"$MANIFEST"; }

# Downloads + verifies the bundle into BUNDLE_TMP (removed by the EXIT trap in main)
# and points REPO/CDH_BIN at it.
fetch_release() {
  local asset="cdh-$DISTRO_TAG-x86_64.tar.gz" base
  base=$(release_base)
  BUNDLE_TMP=$(mktemp -d /tmp/cdh-release.XXXXXX)
  curl -fsSL -o "$BUNDLE_TMP/$asset" "$base/$asset" || return 1
  curl -fsSL -o "$BUNDLE_TMP/SHA256SUMS" "$base/SHA256SUMS" || return 1
  (cd "$BUNDLE_TMP" && grep " $asset\$" SHA256SUMS | sha256sum -c --quiet -) || return 1
  tar -C "$BUNDLE_TMP" -xzf "$BUNDLE_TMP/$asset"
  REPO=$BUNDLE_TMP/cdh CDH_BIN=$BUNDLE_TMP/cdh/cloud-desktop-host
}

# fetch_release_file <name> <dest>: one release asset (ct-install.sh), verified against SHA256SUMS
fetch_release_file() {
  local base sums want
  base=$(release_base)
  sums=$(curl -fsSL "$base/SHA256SUMS") || return 1
  want=$(awk -v f="$1" '$2 == f {print $1}' <<<"$sums")
  [[ -n $want ]] || return 1
  curl -fsSL -o "$2" "$base/$1" || return 1
  [[ "$(sha256sum <"$2" | cut -d' ' -f1)" == "$want" ]]
}

# ════ install-parts/20-helpers.sh ════
# ════════════════════════════════════════════════════════════════
# Host helpers (the shared output/step engine is in shared/20-engine.sh).
#   1. prompts         ask, confirm
#   2. validation      is_supported_distro, IPV4_RE
#   3. container       ct*
#   4. host            GPU discovery, host_uid, mod_persisted, input_isolated
# ════════════════════════════════════════════════════════════════

# ── 1. prompts (read from /dev/tty so `bash -c "$(curl …)"` works too) ──
have_tty() { { : </dev/tty; } 2>/dev/null; }

# ask VAR "question" default [regex]: keeps VAR if it is already set (env)
ask() {
  local var=$1 q=$2 def=$3 re=${4:-.} ans
  [[ -n ${!var} ]] && return 0
  if ! have_tty; then printf -v "$var" '%s' "$def"; return 0; fi
  while :; do
    read -rp " ${BL}?${CL} $q [${def}]: " ans </dev/tty || exit 1
    ans=${ans:-$def}
    [[ $ans =~ $re ]] && break
    echo "   invalid value"
  done
  printf -v "$var" '%s' "$ans"
}

# confirm "question" [y|n, default n]: returns 0 for yes (always yes with YES=1 or no tty)
confirm() {
  local ans def=${2:-n} hint=y/N
  [[ $def == y ]] && hint=Y/n
  ((YES)) && return 0
  have_tty || return 0
  read -rp " ${YW}?${CL} $1 [$hint]: " ans </dev/tty || exit 1
  [[ ${ans:-$def} =~ ^[Yy] ]]
}


# call right after a step whose change needs a CT restart
restart_if_applied() { if ((APPLIED)); then RESTART_CT=1; fi; }

# ── 2. validation ──────────────────────────────────────────────
IPV4_RE='([0-9]{1,3}\.){3}[0-9]{1,3}'

is_supported_distro() {
  local v
  for v in "${SUPPORTED_DISTROS[@]}"; do [[ $v == "$1" ]] && return 0; done
  return 1
}

# ── 3. container ───────────────────────────────────────────────
ct()      { pct exec "$CTID" -- "$@"; }
ct_sh()   { pct exec "$CTID" -- bash -c "$1"; }
ct_up()   { [[ "$(pct status "$CTID" 2>/dev/null)" == "status: running" ]]; }
ct_gid()  { ct getent group "$1" | cut -d: -f3; }
ct_ip()   { ct ip -4 -o addr show dev eth0 2>/dev/null | awk '{sub(/\/.*/, "", $4); print $4; exit}'; }

# ── 4. Proxmox host ────────────────────────────────────────────
host_driver() { cat /sys/module/nvidia/version 2>/dev/null; }

# drm_node card|renderD → /dev/dri/<node> of the chosen NVIDIA GPU
drm_node() {
  local d n
  for d in /sys/class/drm/"$1"*; do
    n=${d##*/}; [[ $n =~ ^$1[0-9]+$ ]] || continue
    [[ "$(cat "$d/device/vendor" 2>/dev/null)" == 0x10de ]] || continue
    [[ -z $NVIDIA_PCI || "$(basename "$(readlink -f "$d/device")")" == "$NVIDIA_PCI" ]] || continue
    echo "/dev/dri/$n"; return 0
  done
  return 1
}

# minor number N of /dev/nvidiaN for the chosen GPU
nvidia_minor() {
  local pci=${NVIDIA_PCI:-$(basename "$(readlink -f "/sys/class/drm/$(basename "$(drm_node card)")/device")")}
  local m; m=$(awk '/^Device Minor:/{print $3}' "/proc/driver/nvidia/gpus/$pci/information" 2>/dev/null)
  echo "${m:-0}"
}

# mod_persisted <module>: listed in /etc/modules or modules-load.d (any file, so a missing /etc/modules is fine)
mod_persisted() {
  local f
  for f in /etc/modules /etc/modules-load.d/*.conf; do
    grep -qsxE "[[:space:]]*$1[[:space:]]*" "$f" && return 0
  done
  return 1
}

# uid on the host of the CT user (unprivileged CT: shift 100000)
host_uid() { local u; u=$(ct id -u "$CT_USER" 2>/dev/null) || u=''; echo $((100000 + ${u:-1000})); }

# true when each CT gets its own /dev/input (needs the cdh_input_guard module)
input_isolated() { [[ $INSTALL_INPUT_GUARD != 0 ]]; }


# ════ install-parts/40-resolve.sh ════
# ── interactive/env resolution: which CT, which distro, which options ──
resolve_ctid() {
  if [[ -z $CTID ]]; then
    have_tty || die "no terminal to ask on: set CTID=<id> (and optionally CT_* settings)"
    header "Container"
    if [[ -n "$(pct list 2>/dev/null | tail -n +2)" ]]; then
      echo "   Existing containers:"; pct list | sed 's/^/     /'
    fi
    ask CTID "Container ID (existing to update it, or a free one to create it)" \
      "$(pvesh get /cluster/nextid 2>/dev/null || echo 100)" '^[1-9][0-9]{2,8}$'
  fi
  [[ $CTID =~ ^[1-9][0-9]{2,8}$ ]] || die "CTID must be a number ≥ 100, got '$CTID'"
  CONF=/etc/pve/lxc/$CTID.conf
}

# ── checks before anything is asked or changed ────────────────
preflight() {
  local c missing=()
  [[ $EUID -eq 0 ]] || die "run as root on the Proxmox host"
  for c in pct pveam pvesm pvesh qm curl tar sha256sum awk sed flock udevadm modprobe; do
    command -v "$c" >/dev/null || missing+=("$c")
  done
  ((${#missing[@]} == 0)) || die "missing on the host: ${missing[*]} (is this a Proxmox VE host?)"

  [[ $CT_USER =~ ^[a-z_][a-z0-9_-]{0,31}$ ]] || die "CT_USER '$CT_USER' is not a valid user name"
  [[ $SHM_SIZE =~ ^[0-9]+[KMG]?$ ]] || die "SHM_SIZE must look like 4G, got '$SHM_SIZE'"
  [[ -z $NVIDIA_PCI || $NVIDIA_PCI =~ ^[0-9a-f]{4}:[0-9a-f]{2}:[0-9a-f]{2}\.[0-7]$ ]] \
    || die "NVIDIA_PCI must look like 0000:01:00.0, got '$NVIDIA_PCI'"
  [[ $INSTALL_INPUT_GUARD =~ ^[01]$ ]] || die "INSTALL_INPUT_GUARD must be 1 or 0, got '$INSTALL_INPUT_GUARD'"
  pvesm status 2>/dev/null | awk 'NR>1{print $1}' | grep -qx "$TEMPLATE_STORAGE" \
    || die "TEMPLATE_STORAGE '$TEMPLATE_STORAGE' is not a Proxmox storage"
}

# values from the environment skip ask(): validate them before a CT is created
validate_new_ct() {
  local n
  for n in CT_DISK CT_CORES CT_MEMORY; do
    [[ ${!n} =~ ^[0-9]+$ ]] || die "$n must be a number, got '${!n}'"
  done
  pvesm status -content rootdir 2>/dev/null | awk 'NR>1{print $1}' | grep -qx "$CT_STORAGE" \
    || die "CT_STORAGE '$CT_STORAGE' is not a storage that can hold container disks"
  [[ -d /sys/class/net/$CT_BRIDGE ]] || die "network bridge '$CT_BRIDGE' does not exist on this host"
}

# existing CT → confirm; free ID → ask creation settings and confirm
resolve_ct() {
  if pct status "$CTID" >/dev/null 2>&1; then
    resolve_existing_ct
  elif ((!CHECK_ONLY)); then
    resolve_new_ct
  fi
}

resolve_existing_ct() {
  CT_NAME=$(pct config "$CTID" | awk '/^hostname:/{print $2}')
  ((CHECK_ONLY)) && return 0
  confirm "Install into existing CT $CTID (${CT_NAME:-?})? Its config may be changed and it may be restarted" \
    || die "aborted"
}

resolve_new_ct() {
  local default_storage
  if qm status "$CTID" >/dev/null 2>&1; then die "ID $CTID is used by a VM"; fi
  default_storage=$(pvesm status -content rootdir 2>/dev/null | awk 'NR>1 && $3=="active"{print $1; exit}' | grep . || echo local-lvm)

  echo "   CT $CTID does not exist and will be created:"
  ask CT_HOSTNAME "Hostname"         "cloud-desktop"   '^[a-zA-Z0-9][a-zA-Z0-9.-]*$'
  ask CT_STORAGE  "Root disk storage" "$default_storage" '^[A-Za-z0-9_.-]+$'
  ask CT_DISK     "Root disk size, GB" 64              '^[0-9]+$'
  ask CT_CORES    "CPU cores"        8                 '^[0-9]+$'
  ask CT_MEMORY   "Memory, MB"       16384             '^[0-9]+$'
  ask CT_BRIDGE   "Network bridge"   vmbr0             '^[A-Za-z0-9_.-]+$'
  resolve_ct_network
  validate_new_ct

  confirm "Create CT $CTID '$CT_HOSTNAME' on $CT_STORAGE (${CT_DISK} GB, $CT_CORES cores, $CT_MEMORY MB, $CT_BRIDGE, ip $CT_IP${CT_GATEWAY:+ via $CT_GATEWAY})?" \
    || die "aborted"
}

# CT_IP = dhcp | a.b.c.d/nn (+ CT_GATEWAY). Env values are validated too, ask() keeps them as is.
resolve_ct_network() {
  ask CT_IP "IPv4 address: dhcp, or static in CIDR form like 192.168.1.50/24" dhcp "^(dhcp|$IPV4_RE/[0-9]{1,2})\$"
  [[ $CT_IP =~ ^(dhcp|$IPV4_RE/[0-9]{1,2})$ ]] || die "CT_IP must be 'dhcp' or a.b.c.d/nn, got '$CT_IP'"
  if [[ $CT_IP == dhcp ]]; then CT_GATEWAY=''; return 0; fi
  ask CT_GATEWAY "Gateway" "$(ip -4 route show default 2>/dev/null | awk '{print $3; exit}')" "^$IPV4_RE\$"
  [[ $CT_GATEWAY =~ ^$IPV4_RE$ ]] || die "static CT_IP needs CT_GATEWAY=a.b.c.d, got '${CT_GATEWAY:-}'"
}

# DISTRO = fedora-NN | ubuntu-NN.NN. An existing running CT decides for itself.
resolve_distro() {
  local ct_distro
  if [[ -n $CT_NAME ]] && ct_up; then
    ct_distro=$(ct sh -c '. /etc/os-release && echo "$ID-$VERSION_ID"' 2>/dev/null || true)
    if [[ -n $ct_distro ]]; then
      [[ -z $DISTRO || $DISTRO == "$ct_distro" ]] || die "CT $CTID runs $ct_distro but $DISTRO was requested (upgrade or recreate the CT first)"
      DISTRO=$ct_distro
    fi
  fi
  if [[ -z $DISTRO ]]; then
    if [[ -z $CT_NAME ]] && ((!CHECK_ONLY)); then
      ask DISTRO "Distro (${SUPPORTED_DISTROS[*]})" "$DEFAULT_DISTRO" '^[a-z]+-[0-9.]+$'
    else
      DISTRO=$DEFAULT_DISTRO
    fi
  fi
  is_supported_distro "$DISTRO" || die "'$DISTRO' has no release bundle; supported: ${SUPPORTED_DISTROS[*]}"
  OS_TYPE=${DISTRO%%-*}
}

resolve_options() {
  if [[ -z $INSTALL_STEAM ]]; then
    confirm "Install Steam + Gamescope + MangoHud?" y && INSTALL_STEAM=1 || INSTALL_STEAM=0
  fi
  [[ $INSTALL_STEAM =~ ^[01]$ ]] || die "INSTALL_STEAM must be 1 or 0, got '$INSTALL_STEAM'"
  [[ $INSTALL_UPDATE_TIMER =~ ^[01]$ ]] || die "INSTALL_UPDATE_TIMER must be 1 or 0, got '$INSTALL_UPDATE_TIMER'"
  ((!FORCE_RESTART || UPDATE)) || die "--force-restart only makes sense with --update"
}

# ════ install-parts/50-phase-host.sh ════
# ── phase: Proxmox host (driver, modules) ──────────────────────
chk_driver() { [[ -n "$(host_driver)" ]] && drm_node renderD; }

# Only what the current boot needs. Settings that survive a host reboot
# (modeset, modules-load.d, udev rule) are pve/host-persist.sh, opt-in.
PERSIST_HINT="pve/host-persist.sh"
chk_modeset() { [[ "$(cat /sys/module/nvidia_drm/parameters/modeset 2>/dev/null)" == Y ]] || why "nvidia_drm modeset is not Y"; }

chk_uinput() { [[ -c /dev/uinput ]] || why "/dev/uinput missing (module not loaded)"; }
do_uinput()  { modprobe uinput; }

chk_uvm() { [[ -c /dev/nvidia-uvm ]] || why "/dev/nvidia-uvm missing"; }
do_uvm()  { nvidia-modprobe -c0 -u; }

# warning only: you may load these some other way (e.g. CUDA/nvidia-smi before the CT starts)
chk_reboot() {
  local r=0
  mod_persisted uinput || { echo "uinput not in /etc/modules-load.d"; r=1; }
  mod_persisted nvidia_uvm || { echo "nvidia_uvm not in /etc/modules-load.d"; r=1; }
  grep -qsE 'nvidia-modprobe.* -u' /etc/udev/rules.d/*.rules || { echo "no udev rule creating /dev/nvidia-uvm"; r=1; }
  return $r
}

phase_host() {
  local out
  header "Host"

  require "NVIDIA driver loaded ($(host_driver || echo none))" chk_driver \
    "install the NVIDIA driver on the host first (nvidia-smi must work)"
  require "nvidia-drm modeset=Y" chk_modeset \
    "set nvidia-drm modeset=1 ($PERSIST_HINT, or yourself) and reboot the host"
  step "uinput loaded" chk_uinput do_uinput
  step "nvidia-uvm device" chk_uvm do_uvm

  if out=$(chk_reboot); then
    msg_ok "uinput + nvidia-uvm set up at boot"
  else
    msg_warn "uinput/nvidia-uvm not set up at boot, load them before starting the CT (or run $PERSIST_HINT)"
    show_why "$out"
  fi
}

# ════ install-parts/51-phase-guard.sh ════
# ── phase: input guard kernel module (skipped with INSTALL_INPUT_GUARD=0) ──
# cdh_input_guard (github.com/chiririll/cdh-input-guard) keeps virtual input devices
# away from the host console. The release has one cdh_input_guard-<kver>.ko per Proxmox
# kernel, the udev rule and SHA256SUMS. Loaded for the current boot only; loading it
# at boot is pve/host-persist.sh.
#
# The module alone does not keep containers apart: it only records, per device, the
# cgroup of the process that created it. The second half of this file uses that to
# give every CT its own /dev/input.
GUARD_KVER=$(uname -r)
GUARD_KO_NAME=cdh_input_guard-$GUARD_KVER.ko
GUARD_KO=/lib/modules/$GUARD_KVER/extra/cdh_input_guard.ko
GUARD_RULE_NAME=71-cdh-virtual-input.rules
GUARD_RULE=/etc/udev/rules.d/$GUARD_RULE_NAME
GUARD_LOAD=/etc/modules-load.d/cdh_input_guard.conf   # written by host-persist.sh

guard_base() {
  if [[ -z $CDH_GUARD_VERSION || $CDH_GUARD_VERSION == latest ]]; then
    echo "https://github.com/$CDH_GUARD_REPO/releases/latest/download"
  else
    echo "https://github.com/$CDH_GUARD_REPO/releases/download/$CDH_GUARD_VERSION"
  fi
}
guard_fetch() { curl -fsSL "$(guard_base)/$1"; }

# expected sha256 of a release asset
guard_sum() {
  local sums sum
  sums=$(guard_fetch SHA256SUMS) || { echo "cannot fetch SHA256SUMS from $CDH_GUARD_REPO (${CDH_GUARD_VERSION:-latest})" >&2; return 1; }
  sum=$(awk -v f="$1" '$2 == f {print $1}' <<<"$sums")
  [[ -n $sum ]] || { echo "release has no $1 (no module built for kernel $GUARD_KVER?)" >&2; return 1; }
  echo "$sum"
}

# chk_guard_file <asset> <dest>: installed file matches the release
chk_guard_file() {
  local want; want=$(guard_sum "$1") || return 1
  [[ -f $2 && $(sha256sum <"$2" | cut -d' ' -f1) == "$want" ]] || why "$2 missing or differs from the release"
}
do_guard_file() {
  local want tmp; want=$(guard_sum "$1")
  tmp=$(mktemp)
  guard_fetch "$1" >"$tmp"
  [[ $(sha256sum <"$tmp" | cut -d' ' -f1) == "$want" ]] || { rm -f "$tmp"; echo "sha256 mismatch for $1"; return 1; }
  install -D -m 0644 "$tmp" "$2"; rm -f "$tmp"
  case $2 in
    *.ko)    depmod -a "$GUARD_KVER" ;;
    *.rules) udevadm control --reload ;;
  esac
}

chk_guard_loaded() { [[ -d /sys/module/cdh_input_guard ]] || why "cdh_input_guard not loaded"; }
do_guard_loaded()  { modprobe cdh_input_guard; }

phase_guard() {
  [[ $INSTALL_INPUT_GUARD != 0 ]] || return 0
  header "Input guard (kernel $GUARD_KVER)"
  step "cdh_input_guard.ko for this kernel" "chk_guard_file $GUARD_KO_NAME $GUARD_KO" "do_guard_file $GUARD_KO_NAME $GUARD_KO"
  step "udev rule $GUARD_RULE_NAME" "chk_guard_file $GUARD_RULE_NAME $GUARD_RULE" "do_guard_file $GUARD_RULE_NAME $GUARD_RULE"
  step "cdh_input_guard loaded" chk_guard_loaded do_guard_loaded
  step "per-container input nodes (cdh-input-node + udev rule)" chk_input_helper do_input_helper
  if grep -qsxF cdh_input_guard "$GUARD_LOAD"; then
    msg_ok "cdh_input_guard loaded at boot"
  else
    msg_warn "cdh_input_guard not loaded at boot: after a host reboot the CT gets no input devices until it is loaded (run $PERSIST_HINT)"
  fi
}

# ── per-container /dev/input ───────────────────────────────────
# Each CT bind-mounts $INPUT_ROOT/<ctid> as its /dev/input, and the host helper
# cdh-input-node (run by udev) puts the nodes of a virtual input device only into the
# directory of the CT that created it. So a CT cannot open another CT's keyboard,
# mouse or gamepad. Without the module (INSTALL_INPUT_GUARD=0) nobody knows who
# created a device, and every CT keeps the host's whole /dev/input.
#
# The directories are under /dev because device nodes need a filesystem mounted
# without "nodev", which /run is not. They are root-owned: the CT must not be able
# to create or rename entries in a directory where root makes device nodes.
INPUT_ROOT=/dev/cdh-input                      # <ctid>/eventN, jsN     (the same paths are in input_helper_txt)
INPUT_CONF=/etc/cdh-input                      # <ctid>.uid: host uid that owns the CT's nodes
INPUT_HELPER=/usr/local/sbin/cdh-input-node
INPUT_NODE_RULE=/etc/udev/rules.d/72-cdh-input-node.rules

input_helper_txt() { get_file bin/cdh-input-node.sh; }

input_node_rule_txt() { get_file udev/72-cdh-input-node.rules; }

chk_input_helper() {
  [[ -x $INPUT_HELPER && "$(cat "$INPUT_HELPER")" == "$(input_helper_txt)" ]] || { why "$INPUT_HELPER missing or outdated"; return; }
  [[ "$(cat "$INPUT_NODE_RULE" 2>/dev/null)" == "$(input_node_rule_txt)" ]] || why "$INPUT_NODE_RULE missing or outdated"
}
do_input_helper() {
  input_helper_txt >"$INPUT_HELPER.new"
  chmod 0755 "$INPUT_HELPER.new"
  mv -f "$INPUT_HELPER.new" "$INPUT_HELPER"    # udev may be running the old one
  input_node_rule_txt >"$INPUT_NODE_RULE"
  udevadm control --reload
  "$INPUT_HELPER" sync
}

# The directory must exist before the CT starts (its mount entry is not "optional"),
# and /dev is empty after a host reboot: tmpfiles.d recreates it early at boot.
# Never remove it while the CT runs: the CT would keep the deleted directory mounted.
input_tmpfiles()     { echo "/etc/tmpfiles.d/cdh-input-$CTID.conf"; }
input_tmpfiles_txt() { echo "d $INPUT_ROOT/$CTID 0755 root root -"; }
chk_input_dir() {
  [[ -d $INPUT_ROOT/$CTID ]] || { why "$INPUT_ROOT/$CTID missing"; return; }
  [[ "$(cat "$(input_tmpfiles)" 2>/dev/null)" == "$(input_tmpfiles_txt)" ]] \
    || why "$(input_tmpfiles) missing or outdated ($INPUT_ROOT/$CTID would be gone after a host reboot)"
}
do_input_dir() {
  input_tmpfiles_txt >"$(input_tmpfiles)"
  install -d -m 0755 -o root -g root "$INPUT_ROOT" "$INPUT_ROOT/$CTID"
}

# host uid of the CT user: the helper makes the CT's nodes 0600 for it
chk_input_owner() {
  [[ "$(cat "$INPUT_CONF/$CTID.uid" 2>/dev/null)" == "$(host_uid)" ]] || why "$INPUT_CONF/$CTID.uid is not $(host_uid)"
}
do_input_owner() {
  install -d -m 0755 "$INPUT_CONF"
  host_uid >"$INPUT_CONF/$CTID.uid"
  "$INPUT_HELPER" sync                         # devices the CT already has
}

# Other CTs on this host that still bind the host's whole /dev/input (main section only).
legacy_input_cts() {
  local f id out=()
  for f in /etc/pve/lxc/*.conf; do
    id=${f##*/}; id=${id%.conf}
    [[ $id != "$CTID" && -f $f ]] || continue
    if awk '/^\[/ {exit} /^lxc\.mount\.entry: \/dev\/input dev\/input / {f=1; exit} END {exit !f}' "$f"; then
      out+=("$id")
    fi
  done
  echo "${out[*]}"
}

# What ct-install.sh does about 60-lxc-virtual-input.rules (it hands every virtual device on the host to
# one uid; only CTs on the shared /dev/input need it): 0 = install it, 1 = this CT has its own /dev/input,
# remove it, keep = other CTs still share /dev/input, leave it alone.
input_isolation_mode() {
  local others
  if ! input_isolated; then echo 0; return; fi
  others=$(legacy_input_cts)
  if [[ -n $others ]]; then
    msg_warn "still on the host's shared /dev/input: CT $others. Re-run install.sh for each: until then they can read CT $CTID's input devices" >&2
    echo keep
  else
    echo 1
  fi
}

# ════ install-parts/52-phase-container.sh ════
# ── phase: the LXC container itself (config, devices, restart) ──
# pveam template name pattern: fedora-44-default, ubuntu-26.04-standard
template_pattern() { case $DISTRO in fedora-*) echo "$DISTRO-default" ;; *) echo "$DISTRO-standard" ;; esac; }
template() { pveam list "$TEMPLATE_STORAGE" 2>/dev/null | awk -v p="$(template_pattern)" '$1 ~ p {print $1}' | sort | tail -1; }
chk_template() { pct status "$CTID" >/dev/null 2>&1 || [[ -n "$(template)" ]]; }
do_template() {
  pveam update
  local t; t=$(pveam available --section system | awk -v p="$(template_pattern)" '$2 ~ p {print $2}' | sort | tail -1)
  [[ -n $t ]] || { echo "no $(template_pattern) template in pveam"; return 1; }
  pveam download "$TEMPLATE_STORAGE" "$t"
}

chk_ct() { pct status "$CTID" >/dev/null 2>&1; }
do_ct() {
  pct create "$CTID" "$(template)" \
    --unprivileged 1 --features nesting=1,fuse=1 --ostype "$OS_TYPE" \
    --hostname "$CT_HOSTNAME" --cores "$CT_CORES" --memory "$CT_MEMORY" --swap 1024 \
    --rootfs "$CT_STORAGE:$CT_DISK" --net0 "name=eth0,bridge=$CT_BRIDGE,ip=$CT_IP${CT_GATEWAY:+,gw=$CT_GATEWAY}"
}

chk_unpriv() { grep -q '^unprivileged: 1' "$CONF" && ! grep -q '^lxc.idmap' "$CONF"; }

chk_nesting() { pct config "$CTID" | grep -q '^features:.*nesting=1'; }
do_nesting()  { pct set "$CTID" --features nesting=1,fuse=1; }

chk_running() { ct_up; }
do_running()  { pct start "$CTID"; sleep 5; }

# The CT's /dev/input: its own directory, filled by the host with the devices the CT
# created (51-phase-guard.sh). Without the input guard nobody knows who created a
# device, so the CT gets the host's /dev/input, which every such CT shares.
input_mount() {
  if input_isolated; then echo "lxc.mount.entry: $INPUT_ROOT/$CTID dev/input none bind,create=dir"
  else echo "lxc.mount.entry: /dev/input dev/input none bind,optional,create=dir"; fi
}

# raw lxc.* keys, kept in the main section (before any [snapshot])
raw_lines() {
  cat <<EOF
lxc.cgroup2.devices.allow: c 13:* rwm
$(input_mount)
lxc.mount.entry: /run/udev mnt/host-udev none bind,ro,optional,create=dir
lxc.cap.drop:
lxc.cap.drop: mac_admin mac_override sys_module sys_pacct sys_rawio sys_time
lxc.mount.entry: tmpfs dev/shm tmpfs rw,nosuid,nodev,mode=1777,size=$SHM_SIZE,create=dir 0 0
EOF
}
main_conf() { sed -e '/^\[/,$d' -e 's/[[:space:]]*$//' "$CONF"; }   # pve may keep "key: " with a trailing space
missing_raw() { local l; while IFS= read -r l; do main_conf | grep -qxF "$l" || echo "$l"; done < <(raw_lines); }
# a /dev/input mount entry other than input_mount: it would be mounted as well
stale_input_mounts() {
  main_conf | grep -E '^lxc\.mount\.entry: [^ ]+ dev/input ' | grep -vxF "$(input_mount)"
  return 0
}
chk_raw() {
  local m s; m=$(missing_raw); s=$(stale_input_mounts)
  [[ -z $m && -z $s ]] && return 0
  [[ -z $m ]] || sed 's/^/missing: /' <<<"$m"
  [[ -z $s ]] || sed 's/^/to remove: /' <<<"$s"
  return 1
}
do_raw() {
  local add tmp
  # drops the wanted entry too if it is there; missing_raw puts it back
  if [[ -n $(stale_input_mounts) ]]; then
    sed -i -E '1,/^\[/{/^lxc\.mount\.entry: [^ ]+ dev\/input /d}' "$CONF"   # main section only
  fi
  add=$(missing_raw)
  # "lxc.cap.drop:" (reset) must come right before the explicit list
  if grep -q '^lxc.cap.drop: mac_admin' <<<"$add" || grep -qx 'lxc.cap.drop:' <<<"$add"; then
    sed -i '1,/^\[/{/^lxc\.cap\.drop:/d}' "$CONF"   # main section only
    add=$(missing_raw)
  fi
  tmp=$(mktemp)
  ADD="$add" awk 'BEGIN{a=ENVIRON["ADD"]} /^\[/ && !d {print a; d=1} {print} END{if(!d) print a}' "$CONF" >"$tmp"
  cat "$tmp" >"$CONF"   # not mv: /etc/pve is pmxcfs
  rm -f "$tmp"
}

chk_user() {
  ct id "$CT_USER" >/dev/null 2>&1 || { why "user '$CT_USER' does not exist"; return; }
  local g groups; groups=$(ct id -nG "$CT_USER")
  for g in render input; do
    grep -qw "$g" <<<"$groups" || { why "'$CT_USER' is not in group $g"; return; }
  done
}
do_user() {
  # ct-install.sh makes sure of the user as well (standalone use); here it exists early so its uid is known
  # for the input guard below. The sudo group exists on Ubuntu, wheel on Fedora.
  ct_sh "id $CT_USER >/dev/null 2>&1 || useradd -m -s /bin/bash $CT_USER"
  ct_sh "for g in video render input wheel sudo; do getent group \$g >/dev/null && usermod -aG \$g $CT_USER; done"
}

# GPU/uinput passthrough entries (devN) wanted in the CT config, one per line
desired_devs() {
  local v r i card render minor p
  v=$(ct_gid video) r=$(ct_gid render) i=$(ct_gid input)
  [[ -n $v && -n $r && -n $i ]] || return 1
  card=$(drm_node card) render=$(drm_node renderD) minor=$(nvidia_minor)
  for p in /dev/nvidia"$minor" /dev/nvidiactl /dev/nvidia-modeset /dev/nvidia-uvm /dev/nvidia-uvm-tools; do
    [[ -e $p ]] && echo "$p,gid=$v,mode=0660"
  done
  echo "$render,gid=$r,mode=0660"
  echo "/dev/uinput,gid=$i,mode=0660"
  echo "$card,gid=$v,mode=0660"           # Sunshine's CUDA/NVENC path opens cardN
}
current_devs() { pct config "$CTID" | sed -n 's/^\(dev[0-9]*\): \(.*\)$/\1 \2/p'; }
chk_devs() {
  local want have; want=$(desired_devs) || return 1; have=$(current_devs | cut -d' ' -f2-)
  [[ "$(sort <<<"$want")" == "$(grep -E '^/dev/(nvidia|dri/|uinput)' <<<"$have" | sort)" ]]
}
do_devs() {
  local want key val spec n; want=$(desired_devs)
  # drop stale GPU/input entries (e.g. cardN renumbered after a reboot)
  while read -r key val; do
    [[ $val =~ ^/dev/(nvidia|dri/|uinput) ]] || continue
    grep -qxF "$val" <<<"$want" || pct set "$CTID" --delete "$key"
  done < <(current_devs)
  while read -r spec; do
    current_devs | cut -d' ' -f2- | grep -qxF "$spec" && continue
    n=0; while current_devs | grep -q "^dev$n "; do n=$((n + 1)); done
    pct set "$CTID" --"dev$n" "$spec"
  done <<<"$want"
}

# --check can't look inside a CT that is missing or stopped: say so, instead of a pile of failures
skip_rest() {
  msg_warn "$1: the remaining steps can't be checked (run without --check to create/start it)"
  SKIPPED=1
}

phase_container() {
  header "Container $CTID${CT_NAME:+ ($CT_NAME)}"
  step "$DISTRO template" chk_template do_template
  step "CT exists" chk_ct do_ct
  if ((CHECK_ONLY)) && ! chk_ct; then skip_rest "CT $CTID does not exist yet"; return 0; fi
  require "CT is unprivileged (default idmap)" chk_unpriv \
    "CT $CTID is privileged or uses a custom lxc.idmap; this script assumes uid shift 100000"

  step "features nesting=1 (Steam bubblewrap)" chk_nesting do_nesting
  restart_if_applied
  # before the CT starts: its config may already mount this directory
  if input_isolated; then step "input directory $INPUT_ROOT/$CTID" chk_input_dir do_input_dir; fi
  step "CT running" chk_running do_running
  step "lxc.conf: input bind, host udev, caps, /dev/shm" chk_raw do_raw
  restart_if_applied
  if ((CHECK_ONLY)) && ! ct_up; then skip_rest "CT $CTID is not running"; return 0; fi

  step "CT user '$CT_USER' (video,render,input,wheel/sudo)" chk_user do_user
  if input_isolated; then step "input devices of CT $CTID owned by '$CT_USER'" chk_input_owner do_input_owner; fi
  step "GPU/uinput passthrough ($(drm_node card 2>/dev/null), $(drm_node renderD 2>/dev/null))" chk_devs do_devs
  restart_if_applied

  if ((RESTART_CT && !CHECK_ONLY)); then
    msg_info "Restarting CT (full stop/start to apply config)"
    { pct stop "$CTID" && pct start "$CTID" && sleep 5; } >>"$LOG" 2>&1 || die "CT restart failed, see $LOG"
    msg_ok "CT restarted"
  fi
}

# ════ install-parts/55-phase-run-inside.sh ════
# ── phase: run ct-install.sh inside the container ──────────────
# Everything inside the CT (udev db, packages, NVIDIA userspace, CDH, Sunshine, Steam, the user
# service, and in --update mode the upgrades) is pve/ct-install.sh. It is pushed in instead of
# fetched there: a fresh CT has no curl. Contract (env vars, exit codes): see its header.
CT_TMP=/tmp/cdh-ct

# a local build (checkout with dist/) replaces the release download inside the CT
local_build() { [[ -z $CDH_VERSION && -x $CDH_BIN && -d $REPO/scripts ]]; }

# CT_INSTALLER: the checkout's copy, else the release asset (verified against SHA256SUMS)
find_ct_installer() {
  [[ -f $CT_INSTALLER ]] && return 0
  BUNDLE_TMP=$(mktemp -d /tmp/cdh-release.XXXXXX)
  CT_INSTALLER=$BUNDLE_TMP/ct-install.sh
  fetch_release_file ct-install.sh "$CT_INSTALLER" \
    || die "could not download/verify ct-install.sh from $CDH_GH_REPO (${CDH_VERSION:-latest}); run from a checkout or set CDH_VERSION"
}

# push_pkg <VAR>: when $VAR is a local file on the host, push it into the CT and point VAR at the copy
push_pkg() {
  local var=$1 src=${!1} dst
  [[ -n $src && -f $src ]] || return 0
  dst=$CT_TMP/${var%_PKG}.${src##*.}
  pct push "$CTID" "$src" "$dst"
  printf -v "$var" '%s' "$dst"
}

restart_ct() {
  msg_info "Restarting CT (full stop/start to apply config)"
  { pct stop "$CTID" && pct start "$CTID" && sleep 5; } >>"$LOG" 2>&1 || die "CT restart failed, see $LOG"
  msg_ok "CT restarted"
}

phase_run_inside() {
  local out rc=0 n flags=() vars
  find_ct_installer
  ct mkdir -p "$CT_TMP"
  pct push "$CTID" "$CT_INSTALLER" "$CT_TMP/ct-install.sh" --perms 0755
  push_pkg SUNSHINE_PKG
  push_pkg CLOUD_MOUSE_PKG
  if local_build; then
    ct mkdir -p "$CT_TMP/bundle"
    tar -C "$REPO" -c scripts configs | pct exec "$CTID" -- tar -C "$CT_TMP/bundle" -x
    pct push "$CTID" "$CDH_BIN" "$CT_TMP/bundle/cloud-desktop-host" --perms 0755
  fi

  vars=(CT_USER="$CT_USER" INSTALL_STEAM="$INSTALL_STEAM" CT_CDH="$CT_CDH"
    CDH_INPUT_ISOLATED="$(input_isolation_mode)"
    CDH_GH_REPO="$CDH_GH_REPO" CDH_VERSION="$CDH_VERSION" CSRF_EXTRA="$CSRF_EXTRA"
    SUNSHINE_PKG="$SUNSHINE_PKG" SUNSHINE_VERSION="$SUNSHINE_VERSION" CLOUD_MOUSE_PKG="$CLOUD_MOUSE_PKG"
    INSTALL_UPDATE_TIMER="$INSTALL_UPDATE_TIMER" CDH_COLOR="$([[ -t 1 ]] && echo 1 || echo 0)")
  if local_build; then vars+=(CDH_LOCAL_BUNDLE="$CT_TMP/bundle"); fi
  if ((CHECK_ONLY)); then flags+=(--check); fi
  if ((UPDATE)); then flags+=(--update); fi
  if ((FORCE_RESTART)); then flags+=(--force-restart); fi

  out=$(mktemp)
  set +e
  pct exec "$CTID" -- env "${vars[@]}" bash "$CT_TMP/ct-install.sh" "${flags[@]}" 2>&1 | tee "$out" | sed '/^NEEDED=/d'
  rc=${PIPESTATUS[0]}
  set -e
  ct rm -rf "$CT_TMP" || true

  case $rc in
    0|12) ;;   # 12: the user session was restarted (update mode), informational
    10) n=$(sed -n 's/^NEEDED=//p' "$out" | tail -1); NEEDED=$((NEEDED + ${n:-0})) ;;
    11) RESTART_CT=1 ;;
    *) rm -f "$out"; die "ct-install.sh failed inside CT $CTID (exit $rc), see its output above and $LOG_CT in the CT" ;;
  esac
  rm -f "$out"
  if ((RESTART_CT && !CHECK_ONLY && rc == 11)); then restart_ct; fi
}

phase_summary() {
  local ip
  echo
  if ((CHECK_ONLY)); then
    if ((NEEDED)); then echo "${YW}$NEEDED step(s) needed.${CL} Run without --check to apply."
    elif ((SKIPPED)); then echo "${YW}Nothing needed in what could be checked,${CL} but the CT itself was not checked: see the warning above."
    else echo "${GN}Everything is in place.${CL}"; fi
    return 0
  fi
  ip=$(ct_ip)
  cat <<EOT
${GN}Done.${CL} Log: $LOG (host), $LOG_CT (in the CT)
  Session: runs at boot as $CT_USER's user service cloud-desktop-host.service. Control it with:
    pct exec $CTID -- runuser -l $CT_USER -c 'XDG_RUNTIME_DIR=/run/user/\$(id -u) systemctl --user restart cloud-desktop-host.service'
    logs: journalctl --user -u cloud-desktop-host.service, and /tmp/cdhost-logs/ in the CT
  Web UI:  https://$ip:47990   (create the Sunshine login on first visit)
  Moonlight: add $ip, enter the PIN in the web UI.
  Set a password for '$CT_USER' if you need it:  pct exec $CTID -- passwd $CT_USER
  Update later:  install.sh --update   (--check --update first to see what would change)
EOT
}

# ════ install-parts/60-main.sh ════
# ── main: the order of things lives here ───────────────────────
# To add a step: write chk_*/do_* in the matching phase part and call `step` from its
# phase_* function. A new phase = a new install-parts/NN-*.sh file + one line below.
main() {
  parse_args "$@"
  trap 'rm -rf "${BUNDLE_TMP:-}"' EXIT

  preflight
  if ((CHECK_ONLY)); then echo "${YW}check mode: nothing will be changed${CL}"; fi

  resolve_ctid
  resolve_ct
  resolve_distro
  resolve_options

  phase_host
  phase_guard
  phase_container
  if ((!SKIPPED)); then   # --check with a missing/stopped CT: nothing to look at inside
    phase_run_inside
  fi
  phase_summary
}

main "$@"
